18	func Quote(parent context.Context, client Client, operationID string) error {
19		const requestBudget = 2 * time.Second
20		deadline := time.Now().Add(requestBudget)
21		encoded, err := json.Marshal(Envelope{OperationID: operationID, Deadline: deadline})
